<template>
  <section class="reg-shell"><header><div><small>{{ $t('clinical360.registration.tab.patient_identity') }}</small><h2>{{ $t('clinical360.registration.tab.registration') }}</h2><p>{{ $t('clinical360.registration.tab.header_subtitle') }}</p></div><v-btn v-if="canEdit" x-small depressed color="#0f766e" dark @click="openEdit"><v-icon x-small left>mdi-account-edit-outline</v-icon>{{ $t('clinical360.registration.tab.update_registration') }}</v-btn></header>
    <div class="identity-band"><div class="barcode"><v-icon>mdi-barcode</v-icon><strong>{{ patient.barcode||$t('clinical360.registration.tab.barcode_pending') }}</strong><small>{{ $t('clinical360.registration.tab.mrn_label', { mrn: patient.mrn||$t('clinical360.registration.tab.pending') }) }}</small></div><div><strong>{{ fullName }}</strong><span>{{ patient.dob||$t('clinical360.registration.tab.dob_not_filed') }} · {{ patient.gender||patient.sex||$t('clinical360.registration.tab.sex_not_filed') }}</span></div><v-btn small outlined color="#0f766e" @click="printBand"><v-icon small left>mdi-printer-outline</v-icon>{{ $t('clinical360.registration.tab.print_wristband') }}</v-btn></div>
    <div class="reg-grid"><section><h3>{{ $t('clinical360.registration.tab.section_identity') }}</h3><p><span>{{ $t('clinical360.registration.tab.full_name') }}</span><b>{{ fullName }}</b></p><p><span>{{ $t('clinical360.registration.tab.date_of_birth') }}</span><b>{{ patient.dob||'-' }}</b></p><p><span>{{ $t('clinical360.registration.tab.sex') }}</span><b>{{ patient.gender||patient.sex||'-' }}</b></p><p><span>{{ $t('clinical360.registration.tab.national_id') }}</span><b>{{ patient.nationalId||'-' }}</b></p></section><section><h3>{{ $t('clinical360.registration.tab.section_contact') }}</h3><p><span>{{ $t('clinical360.registration.tab.phone') }}</span><b>{{ patient.phone||'-' }}</b></p><p><span>{{ $t('clinical360.registration.tab.address') }}</span><b>{{ patient.address||'-' }}</b></p><p><span>{{ $t('clinical360.registration.tab.region') }}</span><b>{{ patient.region||'-' }}</b></p><p><span>{{ $t('clinical360.registration.tab.emergency_contact') }}</span><b>{{ patient.emergencyContact||'-' }}</b></p></section><section><h3>{{ $t('clinical360.registration.tab.section_administrative') }}</h3><p><span>{{ $t('clinical360.registration.tab.payment_class') }}</span><b>{{ patient.paymentClass||patient.insurance||$t('clinical360.registration.tab.self_pay_verify') }}</b></p><p><span>{{ $t('clinical360.registration.tab.language') }}</span><b>{{ patient.preferredLanguage||$t('clinical360.registration.tab.french_english') }}</b></p><p><span>{{ $t('clinical360.registration.tab.phi_basis') }}</span><b>{{ patient.phiAccessBasis||$t('clinical360.registration.tab.treatment') }}</b></p><p><span>{{ $t('clinical360.registration.tab.status') }}</span><b>{{ patient.patientStatus||patient.status||$t('clinical360.registration.tab.active') }}</b></p></section></div>
    <v-dialog v-model="dialog" max-width="720" persistent><v-card><v-card-title class="dialog-title">{{ $t('clinical360.registration.tab.update_patient_registration') }}<v-spacer/><v-btn icon small @click="dialog=false"><v-icon>mdi-close</v-icon></v-btn></v-card-title><v-card-text class="pt-4"><div class="form-grid"><v-text-field v-model="form.firstName" :label="$t('clinical360.registration.tab.first_name')" dense outlined/><v-text-field v-model="form.lastName" :label="$t('clinical360.registration.tab.last_name')" dense outlined/><v-text-field v-model="form.dob" type="date" :label="$t('clinical360.registration.tab.date_of_birth')" dense outlined/><v-select v-model="form.gender" :items="sexOptions" item-value="value" item-text="text" :label="$t('clinical360.registration.tab.sex')" dense outlined/><v-text-field v-model="form.phone" :label="$t('clinical360.registration.tab.phone')" dense outlined/><v-text-field v-model="form.emergencyContact" :label="$t('clinical360.registration.tab.emergency_contact')" dense outlined/><v-text-field v-model="form.address" :label="$t('clinical360.registration.tab.address_village')" dense outlined/><v-text-field v-model="form.region" :label="$t('clinical360.registration.tab.region')" dense outlined/><v-text-field v-model="form.paymentClass" :label="$t('clinical360.registration.tab.payment_insurance_class')" dense outlined/><v-select v-model="form.preferredLanguage" :items="languageOptions" item-value="value" item-text="text" :label="$t('clinical360.registration.tab.preferred_language')" dense outlined/></div></v-card-text><v-card-actions><v-spacer/><v-btn text small @click="dialog=false">{{ $t('clinical360.registration.tab.cancel') }}</v-btn><v-btn small depressed color="#0f766e" dark :loading="saving" @click="save">{{ $t('clinical360.registration.tab.save_changes') }}</v-btn></v-card-actions></v-card></v-dialog>
  </section>
</template>
<script>
export default{name:'Patient360RegistrationTab',props:{patientId:{type:String,required:true},patient:{type:Object,default:()=>({})},role:{type:String,default:''},readOnly:Boolean},data:()=>({dialog:false,saving:false,form:{}}),computed:{canEdit(){return !this.readOnly&&['ADMIN','FRONT_DESK','RECORDS','NURSE'].includes(this.role)},fullName(){return this.patient.name||[this.patient.firstName,this.patient.lastName].filter(Boolean).join(' ')||this.$t('clinical360.registration.tab.unnamed_patient')},sexOptions(){return [['Female','sex_female'],['Male','sex_male'],['Intersex','sex_intersex'],['Unknown','sex_unknown']].map(([value,key])=>({value,text:this.$t(`clinical360.registration.tab.${key}`)}))},languageOptions(){return [['French','lang_french'],['English','lang_english'],['French / English','french_english'],['Other','lang_other']].map(([value,key])=>({value,text:this.$t(`clinical360.registration.tab.${key}`)}))}},methods:{openEdit(){this.form={firstName:this.patient.firstName||this.fullName.split(' ')[0]||'',lastName:this.patient.lastName||this.fullName.split(' ').slice(1).join(' '),dob:this.patient.dob||'',gender:this.patient.gender||this.patient.sex||'',phone:this.patient.phone||'',emergencyContact:this.patient.emergencyContact||'',address:this.patient.address||'',region:this.patient.region||'',paymentClass:this.patient.paymentClass||this.patient.insurance||'',preferredLanguage:this.patient.preferredLanguage||'French / English'};this.dialog=true},async save(){this.saving=true;try{const updates={...this.form,name:[this.form.firstName,this.form.lastName].filter(Boolean).join(' ')};await this.$store.dispatch('clinical/updatePatient',{patientId:this.patientId,updates});await this.$store.dispatch('clinical/createDocument',{patientId:this.patientId,title:'Registration update',category:'Registration',content:'Patient demographics and contact information verified.',status:'Filed'});this.dialog=false;this.$emit('saved')}finally{this.saving=false}},printBand(){const w=window.open('','_blank','width=560,height=360');if(!w)return;const title=this.$t('clinical360.registration.tab.wristband_title');const mrnDob=this.$t('clinical360.registration.tab.wristband_mrn_dob',{mrn:this.patient.mrn||'-',dob:this.patient.dob||'-'});w.document.write(`<html><head><title>${title}</title><style>body{font-family:Arial;padding:24px}.band{border:2px solid #111;padding:18px;width:430px}.code{font-family:monospace;font-size:22px;letter-spacing:2px}</style></head><body><div class="band"><h2>${this.fullName}</h2><p>${mrnDob}</p><div class="code">${this.patient.barcode||this.patient.mrn||this.patientId}</div></div><script>window.print()<\/script></body></html>`);w.document.close()}}}
</script>
<style scoped>
.reg-shell{padding:14px;background:#f8fbfb;min-height:100%}.reg-shell>header{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #0f766e;padding-bottom:10px}.reg-shell small{font-weight:900;color:#64748b}.reg-shell h2{font-size:18px;margin:2px 0}.reg-shell p{margin:0;font-size:12px}.identity-band{display:grid;grid-template-columns:auto 1fr auto;gap:18px;align-items:center;padding:14px;background:#e7f3f1;border:1px solid #99c8c2;margin:12px 0}.identity-band>div{display:flex;flex-direction:column}.barcode strong{font-family:monospace}.reg-grid{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid #cbd5e1;background:white}.reg-grid section{padding:12px;border-right:1px solid #e2e8f0}.reg-grid h3{font-size:13px;color:#0f766e}.reg-grid p{display:flex;justify-content:space-between;gap:10px;border-bottom:1px solid #edf2f7;padding:7px 0}.reg-grid span{color:#64748b}.reg-grid b{text-align:right}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.dialog-title{font-size:16px!important;font-weight:900}@media(max-width:800px){.reg-grid{grid-template-columns:1fr}.identity-band{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}}
</style>
